def encode(text: str) -> str:
    """
    Encodes the string by splitting it into 3-character groups.
    For each full group, rotates the characters left by one position.
    Groups shorter than three characters are left unchanged.
    """
    def rotate_left(group):
        return group[1:] + group[0]

    return ''.join(
        rotate_left(group) if len(group) == 3 else group
        for group in (text[i:i+3] for i in range(0, len(text), 3))
    )

def decode(text: str) -> str:
    """
    Decodes the string by splitting it into 3-character groups.
    For each full group, rotates the characters right by one position.
    Groups shorter than three characters are left unchanged.
    """
    def rotate_right(group):
        return group[-1] + group[:-1]

    return ''.join(
        rotate_right(group) if len(group) == 3 else group
        for group in (text[i:i+3] for i in range(0, len(text), 3))
    )
