def sort_numbers(s: str) -> str:
    # Mapping of number words to their integer values
    num_map = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Reverse mapping for converting back to words
    word_map = {v: k for k, v in num_map.items()}

    # Functional pipeline:
    # 1. Split string into a list of words
    # 2. Map words to their integer values
    # 3. Sort the integers
    # 4. Map integers back to words
    # 5. Join the words into a single string
    return ' '.join(
        map(
            lambda n: word_map[n], 
            sorted(
                map(
                    lambda w: num_map[w], 
                    s.split()
                )
            )
        )
    )

